head.script:
// 테스트 설명, 유효성 값 설정
//  - 담당 범위 : embeddedInput="true" 이면 Column 의 모든 입력창에 적용
//  - 편집 모드 입력창 type 축, 동작 inputType, 미설정 기본값, 브라우저 동작, 모바일 가상 키보드는 _1 담당
//  - embeddedInput 은 가이드상 동작 inputType(text, textImage) Column 에만 설정
scwin.tData = {
    "description" : "[column > P > type]<br/>Cell 이 편집 모드일때 표시되는 입력창의 type 속성값을 설정합니다.",
    "validation" : [
        "Column 의 embeddedInput='true' 이면 Column 의 모든 입력창에 적용됩니다."
    ]
}



// Body Column 정보 (Body Column 인덱스 순)
scwin.bodyInfo = [
    { "id" : "qty", "label" : "수량(text)" },
    { "id" : "tel", "label" : "연락처(textImage)" }
];



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean "2" = true)
    con_type.setValue("number");
    con_embeddedInput.setValue("2");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - type, embeddedInput(con 값) 은 모든 Body Column 에 같은 값으로 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }

    let cType = con_type.getValue();
    let cEmbeddedInput = con_embeddedInput.getText();
    let attr = (cType === '' ? '' : ' type="' + cType + '"') + (cEmbeddedInput === '' ? '' : ' embeddedInput="' + cEmbeddedInput + '"');

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="qty" name="qty" dataType="text"></w2:column>';
    strDlt += '<w2:column id="tel" name="tel" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "qty" : "120", "tel" : "01012345678" },
        { "qty" : "35", "tel" : "0215881234" },
        { "qty" : "8", "tel" : "0317654321" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:400px;height:180px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    for (let i = 0; i < scwin.bodyInfo.length; i++) {
        strTarget += '<w2:column width="180" style="" inputType="text" id="h_' + scwin.bodyInfo[i].id + '" value="' + scwin.bodyInfo[i].label + '"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="180" style="" id="qty" inputType="text"' + attr + '></w2:column>';
    strTarget += '<w2:column width="180" style="" id="tel" inputType="textImage"' + attr + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 편집 모드가 아닌 상태에서 모든 Row 의 Cell 입력창 type 출력
//  - validation 1 : embeddedInput 설정값별 모든 Row 의 내장 입력창 type (getAttribute('type') / .type) 과 Cell 값
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cType = con_type.getValue();
    let cEmbeddedInput = con_embeddedInput.getText();
    bottom.setReturnValue("type : " + (cType === '' ? "(미설정)" : cType) + " / embeddedInput : " + (cEmbeddedInput === '' ? "(미설정)" : cEmbeddedInput) + " / 편집 중 : " + target1.isEditing());

    let rowCnt = dlt_bind.getRowCount();
    for (let r = 0; r < rowCnt; r++) {
        let arr = [];
        for (let c = 0; c < scwin.bodyInfo.length; c++) {
            let td = document.querySelector("td[id*='" + target1.id + "_cell_" + r + "_" + c + "']");
            let el = td ? td.querySelector("input") : null;
            let inText = el ? "getAttribute('type') = " + el.getAttribute("type") + ", .type = " + el.type : "입력창(input) 없음";
            arr.push(scwin.bodyInfo[c].label + " : " + inText + ", Cell 값 = " + dlt_bind.getCellData(r, scwin.bodyInfo[c].id));
        }
        bottom.setReturnValue("Row " + r + " " + arr.join(" / "));
    }
}
